'use strict';
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='ziyat-study-v1', dateKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const plusDays=(s,n)=>{let d=new Date(s+'T12:00:00');d.setDate(d.getDate()+n);return dateKey(d)};
function nextMonday(){let d=new Date();d.setDate(d.getDate()+((8-d.getDay())%7));return dateKey(d)}
const defaults=()=>({version:1,start:nextMonday(),selected:0,settings:{minutes:20,jp:true,simp:true,difficulty:'easy',cj:true},lessons:{},chars:{},activity:[],lastRoute:'lesson'});
let state;try{state=JSON.parse(localStorage.getItem(KEY))||defaults();if(state.version!==1)state=defaults();state.settings={...defaults().settings,...state.settings}}catch{state=defaults()}
let storageOK=true, cardIndex=0, typingIndex=0, typingKind='sentence', typingStarted=0, typingFeedback=null, extraTarget=null, quizResults=null, toastTimeout, cjIndex=0;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true}catch{storageOK=false;$('.status').textContent='⚠ 無法儲存：請檢查瀏覽器設定';toast('進度暫時無法儲存，請允許網站儲存資料。')}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').style.display='none',2800)}
function activity(){let today=dateKey();if(!state.activity.includes(today))state.activity.push(today)}
function lesson(){return DATA.lessons[state.selected]||DATA.lessons[0]}
function rec(){return state.lessons[state.selected]??={read:[],written:{},typed:{},quiz:null,done:false}}
function nextLesson(){return DATA.lessons.findIndex(l=>!state.lessons[l.id]?.done)}
function due(){return Object.entries(state.chars).filter(([t,c])=>(c.status==='review'||c.status==='mastered')&&c.due<=dateKey()).map(([t,c])=>({t,...c}))}
function completed(){return Object.values(state.lessons).filter(l=>l.done).length}
function streak(){let set=new Set(state.activity),d=new Date(),n=0;for(let i=0;i<450;i++){let key=dateKey(d),weekend=d.getDay()===0||d.getDay()===6;if(set.has(key))n++;else if(!weekend&&key!==dateKey())break;d.setDate(d.getDate()-1)}return n}
function mark(t,correct,difficulty){let c=state.chars[t]??={status:'new',correctCount:0,errorCount:0,consecutive:0};c.lastPracticedAt=dateKey();if(difficulty)c.selfRatedDifficulty=difficulty;if(correct){c.correctCount++;c.consecutive++;if(c.consecutive>=3||difficulty==='mastered'){c.status='mastered';c.due=plusDays(dateKey(),14)}else if(c.status==='review')c.due=plusDays(dateKey(),1);else c.status='learning'}else{c.errorCount++;c.consecutive=0;c.status='review';c.due=plusDays(dateKey(),c.errorCount===1?1:c.errorCount===2?3:7)}activity();save()}
function setLesson(id){if(!Number.isInteger(id)||id<0||id>=60)throw Error('課程編號必須介乎 0 至 59。');state.selected=id;cardIndex=0;typingIndex=0;typingFeedback=null;typingStarted=0;extraTarget=null;quizResults=null;save()}
function go(route){if(location.hash==='#'+route)render();else location.hash=route}
function start(id=nextLesson()){setLesson(id<0?59:id);go('lesson')}
function heading(title,sub='',right=''){return `<div class="heading"><div><div class="eyebrow">ZIYAT · DAILY PRACTICE</div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${right}</div>`}
function jp(s){return state.settings.jp?`<small>${esc(s)}</small>`:''}
function characterCards(chars){return `<div class="chargrid">${chars.map((t,i)=>`<button class="charcard" data-card="${esc(t)}"><small>${String(i+1).padStart(2,'0')} ${state.chars[t]?.status==='mastered'?'✓':''}</small><strong>${t}</strong><span>${state.settings.jp?DATA.chars[t].jp:'　'}</span></button>`).join('')}</div>`}
function steps(active){const l=lesson(),r=rec();return `<div class="row between"><a href="#plan" class="muted">← 第 ${l.week} 週 · 第 ${l.day} 天</a><span class="muted">${state.settings.minutes} 分鐘 · ${esc(l.title)}</span></div><div class="steps">${[['lesson','01 認字',r.read.length===6],['writing','02 手寫',Object.keys(r.written).length===6],['typing','03 打字',Object.keys(r.typed).length===3],['quiz','04 小測',!!r.quiz]].map(([route,name,done])=>`<a class="${active===route?'active':''}" href="#${route}">${done?'✓ ':''}${name}</a>`).join('')}</div>`}
function home(){let id=nextLesson(),l=DATA.lessons[id<0?59:id],week=Math.floor(l.id/5),weekDone=DATA.lessons.slice(week*5,week*5+5).filter(x=>state.lessons[x.id]?.done).length;let r=state.lessons[state.selected],resume=r&&!r.done&&(r.read.length||Object.keys(r.written).length||Object.keys(r.typed).length);const weekend=[0,6].includes(new Date().getDay());return heading(id<0?'十二週，字字有進步。':'今天，學好六個字。',weekend?'週末慢慢來。可以預習下一課，或者重溫學過的字。':'每日 20 分鐘，把熟悉的粵語寫出來。',`<span class="datepill">${new Intl.DateTimeFormat('zh-Hant',{month:'long',day:'numeric',weekday:'long'}).format(new Date())}</span>`)+`<section class="lessonhero"><div><span class="tag">${weekend?'下一堂課':'接著學'} · 第 ${l.week} 週 / 第 ${l.day} 天</span><h2>${esc(l.title)}</h2><p>${l.characters.join(' · ')}　<span class="small">${state.settings.minutes} 分鐘，四個小步驟</span></p><div class="row"><button class="primary" data-start="${l.id}">${id<0?'再練一次':'開始今日課程'}　↗</button>${resume?'<button class="secondary" style="color:#f2f4e8" data-action="resume">繼續上次學習</button>':''}</div></div><div class="practicegrid" aria-hidden="true">${l.characters[3]}</div></section><div class="stats"><div class="stat"><small>連續學習<small style="display:block">週末休息不會中斷</small></small><strong>${streak()} <small>天</small></strong></div><div class="stat"><small>本週課程</small><strong>${weekDone} <small>/ 5 課</small></strong></div><a href="#review" class="stat"><small>今天待複習</small><strong>${due().length} <small>個字　↗</small></strong></a></div><div class="heading"><h2>今天的六個字</h2><span class="muted">點一個字，開始認識它　↗</span></div>${characterCards(l.characters)}<div class="cols"><section class="panel"><div class="row between"><h3>這一週，一步一步來</h3><a href="#plan" class="small">完整計劃 ↗</a></div><p class="small">第 ${l.week} 週 · ${weekTheme(l.week)}</p><div class="weekstrip">${DATA.lessons.slice(week*5,week*5+5).map((x,i)=>`<button class="day ${state.lessons[x.id]?.done?'done':x.id===l.id?'today':''}" data-start="${x.id}">週${'一二三四五'[i]}<b>${state.lessons[x.id]?.done?'✓':String(i+1).padStart(2,'0')}</b></button>`).join('')}</div></section><section class="panel"><h3>把二十分鐘留給自己</h3><div class="schedule">${[['lesson','01','生字學習','4'],['writing','02',state.settings.minutes===10?'手寫一遍':'手寫三遍','4'],['typing','03','詞語與句子打字','8'],['quiz','04','每日小測驗','4']].map(([route,no,label,m])=>`<a href="#${route}" data-home-stage="${l.id}"><span><small class="muted">${no}</small>　${label}</span><span class="muted">${state.settings.minutes===10?Number(m)/2:m} 分鐘</span></a>`).join('')}</div></section></div>`}
function lessonDate(id){return plusDays(state.start,Math.floor(id/5)*7+id%5)}
function weekTheme(w){return ['認識自己與時間','日常生活與出行','閱讀、手寫與打字','對話與工作訊息','倉頡字根與字形','常用拆碼與生活用字','字形重溫與鍵位','倉頡與粵拼交替','日常聊天應用','外出與購物訊息','工作與學習筆記','綜合閱讀與複習'][w-1]}
function plan(){return heading('十二週，慢慢變熟悉。','每週一至五，一天一課。錯過也沒關係，接著未完成的課程學。')+`<div class="notice">第 1–4 週：120 個新字（每日 6 字 × 20 課）。第 5–6 週新增 60 字，第 7–12 週以拆字、閱讀和應用複習鞏固。週末自由複習。</div><div class="planweeks" style="margin-top:25px">${Array.from({length:12},(_,i)=>{let ls=DATA.lessons.slice(i*5,i*5+5),count=ls.filter(l=>state.lessons[l.id]?.done).length;return `<section class="panel"><div class="row between"><span class="eyebrow">WEEK ${String(i+1).padStart(2,'0')}</span><span class="muted">${count}/5</span></div><h3>${weekTheme(i+1)}</h3><p class="small">${lessonDate(i*5)} — ${lessonDate(i*5+4)}</p><div class="progressbar"><i style="width:${count*20}%"></i></div><div class="lessonlist">${ls.map(l=>`<button data-start="${l.id}"><span><small>週${'一二三四五'[l.day-1]}</small>　${esc(l.title)}</span><span>${state.lessons[l.id]?.done?'✓':'↗'}</span></button>`).join('')}</div></section>`}).join('')}</div>`}
let detailChar=null;
function detail(t,standalone=false){let c=DATA.chars[t];return `<section class="panel"><div class="detail"><div><div class="writinggrid">${t}</div><div class="jp">${state.settings.jp?c.jp:''}<p class="small">本課讀音</p></div></div><div><div class="row between"><h2>${c.meaning}</h2>${state.settings.simp?`<span class="badge">${c.s===t?'繁簡相同':`簡體：${c.s} → 繁體：${t}`}</span>`:''}</div><dl><dt>部件觀察</dt><dd>${c.parts}</dd><dt>書寫提示</dt><dd>${c.stroke}<br><a class="small inlinebtn" href="https://www.edbchinese.hk/lexlist/" target="_blank" rel="noopener">查閱香港教育局字形、筆順 ↗</a></dd></dl><div class="row">${c.words.map(w=>`<div class="word">${w.t}${jp(w.jp)}</div>`).join('')}</div><div class="example">${c.example}${jp(c.exampleJP)}<button class="inlinebtn small" data-example="${t}">練習這一句 ↗</button></div><div class="actions"><button class="primary" data-master="${t}">✓ 已掌握</button><button class="secondary" data-review="${t}">↺ 需要複習</button>${standalone?'<a class="soft" href="#review">返回字庫</a>':''}</div></div></div></section>`}
function learning(){let l=lesson(),r=rec();return heading('先認識，再記住。',`今天的${l.review?'複習':'生'}字 · ${r.read.length}/6 已看過`)+steps('lesson')+`<div class="cardnav">${l.characters.map((t,i)=>`<button class="${cardIndex===i?'active':''}" data-index="${i}">${t}${r.read.includes(t)?'<small>✓</small>':''}</button>`).join('')}</div>`+detail(l.characters[cardIndex])+`<div class="actions"><button class="secondary" data-action="next-card">看過了，下一個字 →</button><a class="primary" href="#writing">開始手寫練習 →</a></div><p class="small muted">「看過了」記錄學習進度；覺得難的字可加入複習清單。</p>`}
function writing(){let l=lesson(),r=rec();return heading('落筆，讓字留在手上。',`準備紙和筆，每字寫 ${state.settings.minutes===10?'1':'3'} 次，再選擇難度。`)+steps('writing')+`<div class="stack">${l.characters.map(t=>{let c=DATA.chars[t],done=r.written[t];return `<section class="panel"><div class="row"><div class="writinggrid" style="width:105px;height:105px;font-size:74px">${t}</div><div style="flex:1"><h3>${t} <span class="muted">${state.settings.jp?c.jp:''} · ${c.parts}</span></h3><p class="small">${c.stroke}</p><div class="actions" style="margin-top:10px">${[['easy','容易'],['normal','普通'],['hard','困難']].map(([v,label])=>`<button class="${done===v?'primary':'secondary'}" data-written="${t}" data-level="${v}">${done===v?'✓ ':''}我已完成 · ${label}</button>`).join('')}</div></div></div></section>`}).join('')}</div><div class="actions"><a href="#typing" class="primary">開始打字練習 →</a><span class="muted">${Object.keys(r.written).length}/6 字已完成 · 困難字會加入複習</span></div>`}
function targets(){if(extraTarget)return [extraTarget];if(typingKind==='word')return lesson().characters.slice(0,3).map(t=>DATA.chars[t].words[0]);return lesson().sentences}
function typing(){let list=targets();typingIndex=Math.min(typingIndex,list.length-1);let t=list[typingIndex];return heading('把粵語，打成文字。','可以直接輸入粵拼，或用電腦輸入法輸入繁體字。')+steps('typing')+`<section class="panel"><div class="row between"><div class="row"><button class="${typingKind==='sentence'&&!extraTarget?'primary':'secondary'}" data-kind="sentence">句子練習</button><button class="${typingKind==='word'&&!extraTarget?'primary':'secondary'}" data-kind="word">詞語練習</button></div><span class="muted">${extraTarget?'自選例句':`${typingIndex+1} / ${list.length}`}</span></div><div class="target">${t.t}</div>${state.settings.jp?`<div class="targetjp">${t.jp}</div>`:''}<div class="notice" style="margin:20px 0">${state.settings.difficulty==='easy'?'粵拼不用聲調數字；空格和標點不計分。':'進階模式：輸入粵拼時請加上聲調數字；也可直接輸入繁體字。'}<br>例：ngo hok gan daa zi → 我學緊打字。這裡只核對本題答案，不是通用輸入法。</div><form id="typing-form"><label for="typing-input">在這裡輸入<textarea id="typing-input" class="field typeinput" placeholder="慢慢打，準確比速度重要。" autocomplete="off" spellcheck="false" required></textarea></label><div class="row between" style="margin-top:18px"><button class="primary" type="submit">核對答案　↵</button><span class="muted timer" id="typing-time">從第一個字開始計時</span></div></form><div id="typing-feedback" class="feedback" aria-live="polite">${typingFeedback?feedbackHTML(typingFeedback):''}</div></section><div class="actions"><a class="secondary" href="#quiz">前往今日小測 →</a>${lesson().week>=5&&state.settings.cj?'<a class="soft" href="#cangjie">本週加練：倉頡字根 ↗</a>':''}</div>`}
function norm(s,roman=false){s=String(s).normalize('NFKC').toLowerCase().replace(/[\s\p{P}\p{S}]/gu,'');if(roman&&state.settings.difficulty==='easy')s=s.replace(/[1-6]/g,'');return s}
function distance(a,b){let prev=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let row=[i];for(let j=1;j<=b.length;j++)row[j]=Math.min(row[j-1]+1,prev[j]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));prev=row}return prev[b.length]}
function evaluate(input,t){let roman=/^[a-z\s1-6'’.,!?，。！？-]+$/i.test(input),expected=norm(roman?t.jp:t.t,roman),actual=norm(input,roman),errors=distance(actual,expected);let accuracy=Math.round(Math.max(0,1-errors/Math.max(expected.length,actual.length,1))*100);return {correct:actual===expected,accuracy,errors,roman,expected:roman?t.jp:t.t,actual:input,target:t.t}}
function feedbackHTML(f){return `<div class="notice ${f.correct?'success':'error'}"><strong>${f.correct?'✓ 正確！'+esc(f.target):'再看清楚，一起修正。'}</strong><p>正確率 ${f.accuracy}% · 約 ${f.cpm} 字／分鐘 · 用時 ${f.seconds} 秒</p>${!f.correct?`<div>你的輸入：${esc(f.actual)}</div><div>正確答案：${esc(f.expected)}</div><div class="small">${f.errors} 處字元差異；已把本題生字加入複習。</div>`:''}</div><div class="actions"><button class="secondary" data-action="retry-typing">${f.correct?'再練一次':'重做錯誤項目'}</button><button class="primary" data-action="next-typing">${typingIndex===targets().length-1?'查看本課打字結果':'下一句 →'}</button></div>`}
function typingResults(){let entries=Object.values(rec().typed);return heading('慢慢打，也是在進步。','本課三句練習記錄；每句保留最近一次結果。')+`<section class="panel"><div class="row between"><h2>${entries.length}/3 句已練習</h2><strong>${entries.length?Math.round(entries.reduce((s,x)=>s+x.accuracy,0)/entries.length):0}% 平均正確率</strong></div>${lesson().sentences.map((t,i)=>{let f=rec().typed[i];return `<div class="reviewrow"><div class="grow">${t.t}<p class="small">${f?`${f.accuracy}% · 約 ${f.cpm} 字／分鐘${!f.correct?' · 正確答案：'+esc(f.expected):''}`:'尚未練習'}</p></div><button class="secondary" data-retype="${i}">${f?.correct?'重練':'去練習'}</button></div>`}).join('')}<div class="actions"><a class="primary" href="#quiz">開始每日小測 →</a></div></section>`}
function questions(){let cs=lesson().characters.map(t=>DATA.chars[t]),q=[{label:`「${cs[0].s}」對應哪個繁體字？`,answer:cs[0].t,options:[cs[2].t,cs[0].t,cs[1].t],t:cs[0].t},{label:`「${cs[1].t}」在本課讀作甚麼？`,answer:cs[1].jp,options:[cs[1].jp,cs[2].jp,cs[0].jp],t:cs[1].t},{label:`看粵拼選字：${cs[2].jp}`,answer:cs[2].t,options:[cs[1].t,cs[0].t,cs[2].t],t:cs[2].t},{label:`輸入「${cs[3].t}」的粵拼（聲調可省略）`,answer:cs[3].jp,t:cs[3].t,roman:true},{label:`哪個詞語包含「${cs[4].t}」？`,answer:cs[4].words[0].t,options:[cs[0].words[0].t,cs[4].words[0].t,cs[1].words[0].t].filter((v,i,a)=>a.indexOf(v)===i),t:cs[4].t},{label:`「${cs[5].s}」對應哪個繁體字？`,answer:cs[5].t,options:[cs[4].t,cs[5].t,cs[3].t],t:cs[5].t}];if(lesson().week>=5&&state.settings.cj){let c=DATA.cj[(lesson().id-20)%DATA.cj.length];q.push({label:`倉頡第五代：「${c[0]}」的字根「${c[2]}」對應哪些英文字母？`,answer:c[1],t:c[0],cj:true})}return q}
function quiz(){let qs=questions();return heading('試一試，記住了多少？','不用急，答錯的字會留到複習清單。')+steps('quiz')+`<section class="panel"><form id="quiz-form">${qs.map((q,i)=>`<div class="question"><fieldset><legend>${i+1}. ${q.label}</legend>${q.options?`<div class="options">${q.options.map(o=>`<label><input type="radio" name="q${i}" value="${esc(o)}" required> ${o}</label>`).join('')}</div>`:`<input class="field" aria-label="第 ${i+1} 題答案" name="q${i}" autocomplete="off" required>`}</fieldset></div>`).join('')}<div class="actions"><button class="primary" type="submit">交卷，看看結果 →</button></div></form></section>`}
function results(){let result=rec().quiz;if(!result)return heading('先完成今日小測。')+'<a href="#quiz" class="primary">開始小測</a>';let miss=result.answers.filter(a=>!a.correct),r=rec(),ready=r.read.length===6&&Object.keys(r.written).length===6&&Object.keys(r.typed).length===3;return heading('每一次練習，都算數。','看看掌握的部分，再給不熟悉的字一點時間。')+`<section class="panel"><div class="row between"><div><div class="eyebrow">今日小測結果</div><div class="score">${result.score}<span class="muted"> / 100</span></div><p>${result.answers.length-miss.length}/${result.answers.length} 題答對 · 正確率 ${result.score}%</p></div><div class="writinggrid" style="width:120px;height:120px;font-size:83px">${miss.length?'習':'好'}</div></div>${miss.length?`<h3 style="margin-top:25px">這幾題，再練一遍</h3>${miss.map(a=>`<div class="notice error" style="margin:10px 0"><strong>${a.label}</strong><div>你的答案：${esc(a.actual)}</div><div>正確答案：${esc(a.answer)}</div></div>`).join('')}`:'<div class="notice success">全部答對！明天繼續累積。</div>'}<div class="notice" style="margin-top:20px">${ready?'四個環節已完成，可以記下今天的學習。':`還有環節未完成：${r.read.length<6?'認字 '+r.read.length+'/6　':''}${Object.keys(r.written).length<6?'手寫 '+Object.keys(r.written).length+'/6　':''}${Object.keys(r.typed).length<3?'打字 '+Object.keys(r.typed).length+'/3':''}。完成後再記錄整課進度。`}</div><div class="actions">${r.done?'<span class="primary">✓ 這一課已完成</span>':ready?'<button class="primary" data-action="finish">完成今日課程 ✓</button>':'<a class="primary" href="#lesson">返回課程繼續</a>'}<a class="secondary" href="#quiz">再做一次小測</a><a class="soft" href="#review">查看複習清單</a></div></section>`}
function review(){let all=Object.entries(state.chars),pending=all.filter(([t,c])=>c.status==='review'||(c.status==='mastered'&&c.due<=dateKey()));return heading('把不熟悉的字，再見一次。',`今天到期 ${due().length} 字 · 待複習共 ${pending.length} 字`)+`<section class="panel"><h3>我的複習清單</h3>${pending.length?pending.sort((a,b)=>a[1].due.localeCompare(b[1].due)).map(([t,c])=>`<div class="reviewrow"><strong>${t}</strong><div class="grow"><span>${state.settings.jp?DATA.chars[t]?.jp||'':''}</span><p class="small">${c.due<=dateKey()?'今天可以複習':'下次：'+c.due} · 錯誤 ${c.errorCount} 次 · 連續答對 ${c.consecutive} 次</p></div><button class="secondary" data-review-test="${t}">練一練</button><button class="soft" data-card="${t}">看字卡</button></div>`).join(''):'<div class="empty"><h3>暫時沒有待複習的字。</h3><p>學習時按「需要複習」，困難字就會出現在這裡。</p><a class="primary" href="#lesson">繼續學習 →</a></div>'}</section><div class="heading"><h2>生字字庫</h2><span class="muted">180 個字 · ${all.filter(([t,c])=>c.status==='mastered').length} 個已掌握</span></div><label class="small">找一個字<input class="field" id="char-search" placeholder="輸入繁體字、簡體字或粵拼"></label><div id="library" style="margin-top:20px">${characterCards(Object.keys(DATA.chars))}</div>`}
let reviewTestChar=null;
function reviewTest(){let c=DATA.chars[reviewTestChar];if(!c)return review();return heading('不看提示，試著想一想。','輸入粵拼，連續三次答對後會降低複習頻率。')+`<section class="panel"><div class="writinggrid">${c.t}</div><form id="review-form"><label class="formrow">這個字的粵拼<input id="review-answer" class="field" required autocomplete="off" placeholder="聲調可省略"></label><button class="primary">核對答案</button></form><div id="review-feedback" aria-live="polite"></div><div class="actions"><a href="#review" class="secondary">返回複習清單</a></div></section>`}
function cangjie(){let c=DATA.cj[cjIndex];let roots='日月金木水火土竹戈十大中一弓人心手口尸廿山女田難卜';return heading('從字形，找到鍵位。','第 5 週開始，每天認識一點倉頡。以下採用倉頡第五代。')+`${!state.settings.cj?'<div class="notice">倉頡加練已停用，仍可在這裡自由查閱。每日小測不會加入倉頡題。</div>':''}<div class="cols"><section class="panel"><div class="row between"><h3>${cjIndex+1}/20 · 今日拆字</h3><span class="badge">少量加練</span></div><div class="writinggrid" style="margin:20px auto">${c[0]}</div><div class="row between"><button class="secondary" data-action="cj-prev">← 上一個</button><button class="secondary" data-action="cj-next">下一個 →</button></div><p>先看字形，再試著輸入鍵位。基本字根通常可直接取碼，組合字要遵循取碼規則。</p><details style="margin:20px 0"><summary>查看完整拆碼</summary><div class="notice">${c[0]} → ${c[2].split('').join(' · ')} → <strong>${c[1]}</strong></div></details><form id="cj-form"><label>英文字母鍵位<input class="field" id="cj-answer" autocomplete="off" required placeholder="例如：明 → AB"></label><div class="actions"><button class="primary">核對拆碼</button></div></form><div id="cj-feedback" aria-live="polite"></div></section><section class="panel"><h3>字根鍵位表</h3><p class="small">先熟悉日、月、木、人、口。X 是「難」字鍵；Z 為特殊用途，不是一般字根。</p><div class="rootgrid">${roots.split('').map((t,i)=>`<div>${t}<small>${String.fromCharCode(65+i)}</small></div>`).join('')}</div><div class="notice" style="margin-top:20px">字形部件不一定等於倉頡字根。例如「好」觀察為女＋子，完整倉頡碼是女弓木（VND）。</div><a href="#quiz" class="secondary" style="margin-top:20px">回到每日小測 →</a></section></div>`}
function progress(){let comp=completed(),mastered=Object.values(state.chars).filter(c=>c.status==='mastered').length,typed=Object.values(state.lessons).flatMap(r=>Object.values(r.typed));return heading('你走過的每一步。','記下已完成的課程，也留意需要再練習的字。')+`<div class="stats"><div class="stat"><small>完成課程</small><strong>${comp}<small> / 60</small></strong></div><div class="stat"><small>已掌握生字</small><strong>${mastered}<small> / 180</small></strong></div><div class="stat"><small>打字平均正確率</small><strong>${typed.length?Math.round(typed.reduce((s,t)=>s+t.accuracy,0)/typed.length):'—'}<small>${typed.length?'%':''}</small></strong></div></div><section class="panel"><div class="row between"><h3>12 週的學習足跡</h3><span class="muted">${Math.round(comp/60*100)}%</span></div><div class="progressbar" style="margin:15px 0 25px"><i style="width:${comp/60*100}%"></i></div><div class="history">${DATA.lessons.map(l=>`<a href="#lesson" data-select="${l.id}" class="${state.lessons[l.id]?.done?'done':''}" title="第 ${l.week} 週：${l.title}">${state.lessons[l.id]?.done?'✓':l.id+1}</a>`).join('')}</div><p class="small">綠色為已完成課程 · 點選數字可回到該課</p></section><div class="cols"><section class="panel"><h3>最近的練習</h3>${state.activity.length?state.activity.slice().sort().reverse().slice(0,7).map(d=>`<div class="reviewrow">✓　${d}<span class="muted">完成了學習練習</span></div>`).join(''):'<p>第一個學習足跡，從今天開始。</p>'}</section><section class="panel"><h3>複習節奏</h3><p>第 1 次錯誤：隔天複習</p><p>第 2 次錯誤：3 天後複習</p><p>第 3 次或以上：7 天後複習</p><p>連續 3 次正確：延長至 14 天</p><a class="primary" href="#review" style="margin-top:18px">查看 ${due().length} 個到期生字 →</a></section></div>`}
function settings(){let s=state.settings;return heading('用自己的節奏學。','這些設定與進度只保存在目前的瀏覽器，不會跨裝置同步。')+`<section class="panel"><div class="setting"><div><h3>每日學習目標</h3><p class="small">快速模式縮短時間，手寫每字一遍。</p></div><select id="setting-minutes" class="field" style="width:auto"><option value="20" ${s.minutes===20?'selected':''}>完整 20 分鐘</option><option value="10" ${s.minutes===10?'selected':''}>快速 10 分鐘</option></select></div>${[['jp','顯示粵拼','在生字、詞語與例句下顯示粵拼。'],['simp','顯示簡體字對照','幫助比較兩種字形。'],['cj','加入倉頡內容','第 5 週起加入倉頡小測題。']].map(([key,title,sub])=>`<label class="setting"><div><h3>${title}</h3><p class="small">${sub}</p></div><input type="checkbox" data-setting="${key}" ${s[key]?'checked':''}></label>`).join('')}<div class="setting"><div><h3>打字練習難度</h3><p class="small">進階模式核對粵拼聲調數字。</p></div><select id="setting-difficulty" class="field" style="width:auto"><option value="easy" ${s.difficulty==='easy'?'selected':''}>入門 · 不需聲調</option><option value="advanced" ${s.difficulty==='advanced'?'selected':''}>進階 · 包含聲調</option></select></div><div class="setting"><div><h3>重置目前課程</h3><p class="small">清除第 ${lesson().week} 週第 ${lesson().day} 天的環節與成績，保留字庫及其他課程。</p></div><button class="danger" data-action="reset-lesson">重置這一課</button></div></section><section class="panel" style="margin-top:22px"><h3>電腦輸入法與學習資料</h3><p>未安裝輸入法也可以在本站直接練習粵拼；要在其他軟件打中文，可以參考以下說明。</p><div class="actions"><a class="secondary" href="https://jyutping.app/mac/" target="_blank" rel="noopener">macOS 粵拼安裝 ↗</a><a class="secondary" href="https://jyutping.net/" target="_blank" rel="noopener">Windows 粵拼說明 ↗</a><a class="secondary" href="https://jyutping.org/learn/" target="_blank" rel="noopener">認識粵拼 ↗</a></div><p class="small" style="margin-top:22px">粵拼資料參照 <a class="inlinebtn" href="https://github.com/rime/rime-cantonese" target="_blank" rel="noopener">CanCLID / Rime Cantonese</a>（<a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a>），已選編及加入課程例句；多音字以本課語境為準。筆順請配合<a class="inlinebtn" href="https://www.edbchinese.hk/lexlist/" target="_blank" rel="noopener">香港教育局字形表</a>核對。</p><p class="small">按需求中的每天 6 個新字計算，首 4 週為 120 字；本計劃在第 6 週累積至 180 字。</p></section>`}
function render(){let route=location.hash.slice(1)||'home';if(route.indexOf('jp-')===0)return;let titles={home:'今日學習',plan:'繁體字學習',lesson:'生字學習',character:'生字詳情',writing:'手寫練習',typing:'打字練習','typing-results':'打字結果',quiz:'每日小測',results:'測驗結果',review:'生字與複習','review-test':'複習小測',cangjie:'倉頡小教室',progress:'學習足跡',settings:'學習設定'};let views={home,plan,lesson:learning,writing,typing,'typing-results':typingResults,quiz,results,review,'review-test':reviewTest,cangjie,progress,settings,character:()=>heading('一個字，慢慢認識。')+detail(detailChar||lesson().characters[0],true)};if(!views[route])route='home';if(['lesson','writing','typing','quiz','results'].includes(route)){state.lastRoute=route;save()}$('#app').innerHTML=views[route]();$('#breadcrumb').textContent='我的學習 / '+titles[route];$$('nav a').forEach(a=>{let active=a.hash==='#'+route;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.title=titles[route]+' · 字日';bind();window.scrollTo(0,0)}
function bind(){const on=(selector,event,fn)=>$$(selector).forEach(el=>el.addEventListener(event,fn));on('[data-home-stage]','click',e=>setLesson(Number(e.currentTarget.dataset.homeStage)));on('[data-start]','click',e=>start(Number(e.currentTarget.dataset.start)));on('[data-select]','click',e=>{setLesson(Number(e.currentTarget.dataset.select));if(location.hash==='#lesson')render()});on('[data-card]','click',e=>{detailChar=e.currentTarget.dataset.card;go('character')});on('[data-index]','click',e=>{cardIndex=Number(e.currentTarget.dataset.index);render()});on('[data-master]','click',e=>{let t=e.currentTarget.dataset.master;mark(t,true,'mastered');if(lesson().characters.includes(t)&&!rec().read.includes(t))rec().read.push(t);save();toast('已記錄掌握：'+t);render()});on('[data-review]','click',e=>{let t=e.currentTarget.dataset.review;mark(t,false);if(lesson().characters.includes(t)&&!rec().read.includes(t))rec().read.push(t);save();toast('已加入複習：'+t);render()});on('[data-written]','click',e=>{let {written:t,level}=e.currentTarget.dataset;let previous=rec().written[t];rec().written[t]=level;if(previous!==level)mark(t,level!=='hard',level);save();render()});on('[data-example]','click',e=>{let c=DATA.chars[e.currentTarget.dataset.example];extraTarget={t:c.example,jp:c.exampleJP};typingIndex=0;typingFeedback=null;typingStarted=0;go('typing')});on('[data-kind]','click',e=>{typingKind=e.currentTarget.dataset.kind;typingIndex=0;extraTarget=null;typingStarted=0;typingFeedback=null;render()});on('[data-retype]','click',e=>{typingIndex=Number(e.currentTarget.dataset.retype);extraTarget=null;typingKind='sentence';typingStarted=0;typingFeedback=null;go('typing')});on('[data-review-test]','click',e=>{reviewTestChar=e.currentTarget.dataset.reviewTest;go('review-test')});on('[data-setting]','change',e=>{state.settings[e.currentTarget.dataset.setting]=e.currentTarget.checked;save();toast('設定已儲存')});on('#setting-minutes','change',e=>{state.settings.minutes=Number(e.currentTarget.value);save();toast('學習目標已更新')});on('#setting-difficulty','change',e=>{state.settings.difficulty=e.currentTarget.value;save();toast('難度已更新')});on('#char-search','input',e=>{let q=e.currentTarget.value.trim().toLowerCase();$('#library').innerHTML=characterCards(Object.values(DATA.chars).filter(c=>[c.t,c.s,c.jp].some(x=>x.includes(q))).map(c=>c.t));$$('#library [data-card]').forEach(el=>el.addEventListener('click',()=>{detailChar=el.dataset.card;go('character')}))});on('#typing-input','input',()=>{if(!typingStarted)typingStarted=Date.now();$('#typing-time').textContent='練習中 · '+Math.max(1,Math.round((Date.now()-typingStarted)/1000))+' 秒'});on('#typing-form','submit',e=>{e.preventDefault();let input=$('#typing-input').value.trim();if(!input)return;let t=targets()[typingIndex],f=evaluate(input,t),seconds=Math.max(1,Math.round((Date.now()-(typingStarted||Date.now()))/1000));Object.assign(f,{seconds,cpm:Math.round(norm(t.t).length*(f.accuracy/100)*60/seconds),date:dateKey()});typingFeedback=f;if(!extraTarget&&typingKind==='sentence')rec().typed[typingIndex]=f;for(let ch of new Set(t.t))if(lesson().characters.includes(ch))mark(ch,f.correct);activity();save();$('#typing-feedback').innerHTML=feedbackHTML(f);bindFeedback()});on('#quiz-form','submit',e=>{e.preventDefault();let fd=new FormData(e.currentTarget);let answers=questions().map((q,i)=>{let actual=String(fd.get('q'+i)||'');let correct=q.roman?norm(actual,true).replace(/[1-6]/g,'')===norm(q.answer,true).replace(/[1-6]/g,''):norm(actual)===norm(q.answer);if(DATA.chars[q.t])mark(q.t,correct);return {...q,actual,correct}});rec().quiz={score:Math.round(answers.filter(a=>a.correct).length/answers.length*100),answers,date:dateKey()};activity();save();go('results')});on('#review-form','submit',e=>{e.preventDefault();let c=DATA.chars[reviewTestChar],input=$('#review-answer').value;let correct=norm(input,true).replace(/[1-6]/g,'')===norm(c.jp,true).replace(/[1-6]/g,'');mark(c.t,correct);$('#review-feedback').innerHTML=`<div class="notice ${correct?'success':'error'}" style="margin-top:20px">${correct?'✓ 正確！':'再練一下。'} ${c.t} → ${c.jp}<br>下次複習：${state.chars[c.t].due}</div>`;$('#review-form button').disabled=true});on('#cj-form','submit',e=>{e.preventDefault();let c=DATA.cj[cjIndex],correct=$('#cj-answer').value.toUpperCase().replace(/\s/g,'')===c[1];if(DATA.chars[c[0]])mark(c[0],correct);$('#cj-feedback').innerHTML=`<div class="notice ${correct?'success':'error'}" style="margin-top:20px">${correct?'✓ 正確！':'再看一遍：'}${c[0]} → ${c[2]} → ${c[1]}</div>`;activity();save()});on('[data-action]','click',e=>action(e.currentTarget.dataset.action))}
function bindFeedback(){$$('#typing-feedback [data-action]').forEach(el=>el.addEventListener('click',()=>action(el.dataset.action)))}
function action(a){if(a==='resume'){go(state.lastRoute||'lesson')}else if(a==='next-card'){let t=lesson().characters[cardIndex];if(!rec().read.includes(t))rec().read.push(t);activity();save();if(cardIndex<5){cardIndex++;render()}else go('writing')}else if(a==='retry-typing'){typingFeedback=null;typingStarted=0;render();$('#typing-input').focus()}else if(a==='next-typing'){typingFeedback=null;typingStarted=0;if(typingIndex<targets().length-1){typingIndex++;render()}else go('typing-results')}else if(a==='finish'){let r=rec();if(r.read.length!==6||Object.keys(r.written).length!==6||Object.keys(r.typed).length!==3||!r.quiz){toast('請先完成四個學習環節。');return}r.done=true;r.completedAt=dateKey();activity();save();toast('今天辛苦了！這一課已完成。');go('home')}else if(a==='cj-prev'||a==='cj-next'){cjIndex=(cjIndex+(a==='cj-next'?1:DATA.cj.length-1))%DATA.cj.length;render()}else if(a==='reset-lesson'){if(confirm(`確定清除第 ${lesson().week} 週第 ${lesson().day} 天的環節與成績？字庫和其他課程會保留。`)){delete state.lessons[state.selected];save();toast('目前課程已重置');render()}}}
window.addEventListener('hashchange',render);render();
if(document.modelContext?.registerTool){const controller=new AbortController();const tools=[{name:'get_learning_progress',description:'Read completed lessons, due characters and the next unfinished lesson.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({completed:completed(),total:60,due:due().map(c=>c.t),nextLesson:nextLesson()+1})},{name:'start_learning_lesson',description:'Open a lesson without completing it or changing its scores.',inputSchema:{type:'object',properties:{lessonNumber:{type:'integer',minimum:1,maximum:60}},required:['lessonNumber'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!Number.isInteger(input.lessonNumber)||input.lessonNumber<1||input.lessonNumber>60)throw Error('lessonNumber must be an integer from 1 to 60');setLesson(input.lessonNumber-1);history.replaceState(null,'','#lesson');render();return {lessonNumber:input.lessonNumber,title:lesson().title}}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>controller.abort(),{once:true})}
